// PlanControlFlags is a bitfield (Flags of PlanControl).
type PlanControlFlags uint16

const (
	// PlanControlFlags_CALIBRATE: Calibrate Vehicle.
	PlanControlFlags_CALIBRATE PlanControlFlags = 0x1
	// PlanControlFlags_IGNORE_ERRORS: Ignore Errors.
	PlanControlFlags_IGNORE_ERRORS PlanControlFlags = 0x2
)

// String returns the IMC abbreviations of the bits set, separated by '|'.
func (v PlanControlFlags) String() string {
	var parts []string
	rest := v
	if v&PlanControlFlags_CALIBRATE != 0 {
		parts = append(parts, "CALIBRATE")
		rest &^= PlanControlFlags_CALIBRATE
	}
	if v&PlanControlFlags_IGNORE_ERRORS != 0 {
		parts = append(parts, "IGNORE_ERRORS")
		rest &^= PlanControlFlags_IGNORE_ERRORS
	}
	if rest != 0 {
		parts = append(parts, fmt.Sprintf("0x%X", uint16(rest)))
	}
	return strings.Join(parts, "|")
}

