// PlanStatisticsProperties is a bitfield (Properties of PlanStatistics).
type PlanStatisticsProperties uint8

const (
	// PlanStatisticsProperties_BASIC: Basic Plan.
	PlanStatisticsProperties_BASIC PlanStatisticsProperties = 0x0
	// PlanStatisticsProperties_NONLINEAR: Nonlinear.
	PlanStatisticsProperties_NONLINEAR PlanStatisticsProperties = 0x1
	// PlanStatisticsProperties_INFINITE: Infinite.
	PlanStatisticsProperties_INFINITE PlanStatisticsProperties = 0x2
	// PlanStatisticsProperties_CYCLICAL: Cyclical.
	PlanStatisticsProperties_CYCLICAL PlanStatisticsProperties = 0x4
	// PlanStatisticsProperties_ALL: All.
	PlanStatisticsProperties_ALL PlanStatisticsProperties = 0x7
)

// String returns the IMC abbreviations of the bits set, separated by '|'.
func (v PlanStatisticsProperties) String() string {
	var parts []string
	rest := v
	if v&PlanStatisticsProperties_NONLINEAR != 0 {
		parts = append(parts, "NONLINEAR")
		rest &^= PlanStatisticsProperties_NONLINEAR
	}
	if v&PlanStatisticsProperties_INFINITE != 0 {
		parts = append(parts, "INFINITE")
		rest &^= PlanStatisticsProperties_INFINITE
	}
	if v&PlanStatisticsProperties_CYCLICAL != 0 {
		parts = append(parts, "CYCLICAL")
		rest &^= PlanStatisticsProperties_CYCLICAL
	}
	if rest != 0 {
		parts = append(parts, fmt.Sprintf("0x%X", uint8(rest)))
	}
	return strings.Join(parts, "|")
}

