// CreateTyped returns a new typed message by abbreviation, set from msg when it is not nil.
func (p *Protocol) CreateTyped(abbrev string, msg *Message) (IMessage, error) {
	id, ok := MessageID(abbrev)
	if !ok {
		return nil, fmt.Errorf("unknown typed message: %s", abbrev)
	}
	m := NewMessage(id)
	if msg != nil {
		return m, m.FromMessage(msg)
	}
	return m, nil
}

